// Phone form and offline Badge preview; compiled into Settings, no external assets.
static const char page[] =
    "<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'>"
    "<title>Badge settings</title><style>"
    "body{font:16px system-ui,sans-serif;margin:0 auto;max-width:34em;padding:1em}"
    "fieldset{border:1px solid #ccc;border-radius:8px;margin:0 0 1em}"
    "input,textarea,button,select{font:inherit;box-sizing:border-box;width:100%;padding:.4em;margin:.2em 0 .6em}"
    "input[type=radio],input[type=checkbox]{width:auto}canvas{width:100%;border:1px solid #ccc}"
    "button{background:#900;color:#fff;border:0;border-radius:8px;padding:.7em}small{color:#666}"
    "</style><h2>Badge settings</h2>"
    "<fieldset><legend>Username</legend><input id=name maxlength=12 placeholder='up to 12 characters'>"
    "<small>Top bar and other badges' Radar.</small></fieldset>"
    "<fieldset><legend>Wi-Fi the badge joins</legend>"
    "<label>Nearby networks<select id=networks aria-describedby=netstatus><option value=''>Loading saved network...</option></select></label>"
    "<button type=button id=rescan>Refresh networks</button><small id=netstatus role=status>Loading cached networks...</small>"
    "<label>Network name (or type a hidden network)<input id=ssid maxlength=32 autocomplete=off></label>"
    "<label>Password<input id=pass maxlength=63 autocomplete=off></label></fieldset>"
    "<fieldset><legend>Codex Board</legend>Feed URL<input id=cb_url maxlength=240 "
    "placeholder='http://192.168.1.10:8765/feed.txt'>"
    "<small>Leave blank for USB. For Wi-Fi, enter the Linux collector or Mac relay address.</small></fieldset>"
    "<fieldset><legend>Badge app</legend>"
    "<label><input type=radio name=m id=mt checked> Text</label> <label><input type=radio name=m id=mi> Picture</label>"
    "<div id=bt><label>Subject<textarea id=badge_subject rows=2 maxlength=256></textarea></label>"
    "<label>Body<textarea id=badge_body rows=5 maxlength=1000></textarea></label>"
    "<small>Subject: up to 256 characters. Body: up to 1000. Plain English letters, numbers, punctuation and line breaks. "
    "Leave either empty to give the other the full screen.</small>"
    "<canvas id=pv width=960 height=624 aria-label=\"Badge text preview\"></canvas><small id=pst>Loading preview...</small></div>"
    "<div id=bi hidden><input type=file id=file accept='image/*'>"
    "Threshold <input type=range id=th min=0 max=255 value=128>"
    "<label><input type=checkbox id=dit checked> Dither</label>"
    "<canvas id=cv width=960 height=624></canvas><small id=ist></small></div></fieldset>"
    "<fieldset><legend>Weather location</legend>"
    "<label><input type=radio name=w id=wc checked> Place name</label> <label><input type=radio name=w id=wn> Coordinates</label>"
    "<div id=wcd><input id=wx_city maxlength=64 placeholder='Pasadena (default), or e.g. Istanbul'>"
    "<small>The Weather app looks it up online.</small></div>"
    "<div id=wnd hidden>Paste a Google Maps link<input id=link placeholder='https://www.google.com/maps/@40.4,-3.7,12z'>"
    "Latitude<input id=wx_lat inputmode=decimal>Longitude<input id=wx_lon inputmode=decimal>"
    "<small>Or in Google Maps long-press a place and copy the coordinates (short maps.app.goo.gl links do not "
    "work: the badge has no internet to follow them).</small></div>"
    "Temperature<select id=wx_unit><option value=''>Celsius<option value=F>Fahrenheit</select></fieldset>"
    "<fieldset><legend>Clock</legend>Time zone<select id=tz><option value=''>US Pacific"
    "<option value='MST7MDT,M3.2.0,M11.1.0'>US Mountain<option value=MST7>Arizona"
    "<option value='CST6CDT,M3.2.0,M11.1.0'>US Central<option value='EST5EDT,M3.2.0,M11.1.0'>US Eastern"
    "<option value=UTC0>UTC<option value='GMT0BST,M3.5.0/1,M10.5.0'>UK, Ireland, Portugal"
    "<option value='CET-1CEST,M3.5.0,M10.5.0/3'>Central Europe<option value='EET-2EEST,M3.5.0/3,M10.5.0/4'>Eastern Europe"
    "<option value='<+03>-3'>Turkey, Moscow<option value='IST-5:30'>India<option value='CST-8'>China, Singapore"
    "<option value='JST-9'>Japan, Korea<option value='AEST-10AEDT,M10.1.0,M4.1.0/3'>Sydney</select></fieldset>"
    "<fieldset><legend>Sound</legend>Speaker port (without a Cricket)<select id=snd_sao><option value=''>SAO2"
    "<option value=1>SAO1<option value=3>SAO3<option value=0>None</select></fieldset>"
    "<button id=save>Save and restart the badge</button><p id=st></p><script>"
    "var K=['name','ssid','pass','badge_subject','badge_body','wx_city','wx_lat','wx_lon','wx_unit','cb_url','tz','snd_sao'],$=function(i){return document.getElementById(i)},"
    "img=null,gray=null,hadImg=false,font=null,badgeId='0000',badgeEdited=false,cfgReady=false;"
    "fetch('/cfg').then(function(r){return r.json()}).then(function(c){if(c.tz&&![].some.call($('tz').options,function(o){return o.value==c.tz}))$('tz').add(new Option(c.tz,c.tz));K.forEach(function(k){$(k).value=c[k]||''});"
    "if(!c.badge_subject&&!c.badge_body)$('badge_body').value=c.badge_text||'';badgeId=c.id;preview();"
    "hadImg=c.img;if(!c.wx_city&&c.wx_lat)$('wn').checked=true;if(c.img){$('mi').checked=true;$('ist').textContent='A picture is saved; choose a file to replace it.'}mode();cfgReady=true;loadNetworks(false)}).catch(function(){$('st').textContent='Settings could not load. Reopen this page before saving.'});"
    "function mode(){$('bt').hidden=$('mi').checked;$('bi').hidden=!$('mi').checked;"
    "$('wcd').hidden=$('wn').checked;$('wnd').hidden=!$('wn').checked}"
    "$('mt').onchange=$('mi').onchange=$('wc').onchange=$('wn').onchange=mode;"
    // No idle polling: only a requested scan gets a bounded series of cache-status reads.
    "function networkOptions(data){var name=$('ssid').value,list=$('networks');list.options.length=0;"
    "list.add(new Option(name?name+' (current)':'Choose a nearby network',name));"
    "data.networks.forEach(function(n){if(n.ssid!==name)list.add(new Option(n.ssid,n.ssid))});list.value=name;"
    "var t=data.busy?'Scanning; you can keep editing.':!data.available?'Scanning unavailable. Reopen Settings to retry; manual entry is available.':data.error?'Scan failed; cached list kept. Manual entry is available.':"
    "data.networks.length?'Cached '+data.age+' seconds ago.':'No visible networks found. Type the name manually.';"
    "if(data.age>120&&!data.busy)t+=' List may be stale.';if(data.omitted)t+=' Some non-text names were omitted.';"
    "if(data.retry_after&&!data.busy&&data.available)t+=' Refresh available in '+data.retry_after+' seconds.';"
    "$('netstatus').textContent=t;$('rescan').disabled=data.busy||!data.available}"
    "$('networks').onchange=function(){if(this.value)$('ssid').value=this.value};"
    "function loadNetworks(refresh,tries){tries=tries||0;$('rescan').disabled=true;"
    "if(typeof AbortController==='undefined'){$('netstatus').textContent='Network lookup unavailable in this browser. Enter the network name manually.';$('rescan').disabled=false;return Promise.resolve()}"
    "var controller=new AbortController(),timer=setTimeout(function(){controller.abort()},4000);"
    "return fetch(refresh?'/networks/scan':'/networks',{method:refresh?'POST':'GET',cache:'no-store',signal:controller.signal})"
    ".then(function(r){if(!r.ok&&r.status!==429&&r.status!==503)throw 0;return r.json()}).then(function(data){clearTimeout(timer);"
    "networkOptions(data);if(data.busy){if(tries<15)setTimeout(function(){loadNetworks(false,tries+1)},500);"
    "else{$('netstatus').textContent='Scan is taking too long. Keep typing or refresh later.';$('rescan').disabled=false}}})"
    ".catch(function(){clearTimeout(timer);$('netstatus').textContent='Network list unavailable. Your typed name is unchanged; try Refresh or enter it manually.';$('rescan').disabled=false})}"
    "$('rescan').onclick=function(){loadNetworks(true)};"
    // Preview stays offline; /badge-font is just the existing 1 KB font, fetched once.
    "fetch('/badge-font').then(function(r){if(!r.ok)throw 0;return r.arrayBuffer()}).then(function(b){"
    "if(b.byteLength!==1024)throw 0;font=new Uint8Array(b);preview()}).catch(function(){$('pst').textContent='Preview unavailable. Reopen Settings to retry.'});"
    "function normalise(t){return t.replace(/\\r\\n?/g,'\\n').replace(/\\t/g,' ').replace(/[^\\x20-\\x7e\\n]/gu,'?').replace(/^[ \\n]+|[ \\n]+$/g,'')}"
    "function wrap(t,cols){var lines=[],p=0;do{var n=0,space=-1;while(t[p+n]&&t[p+n]!='\\n'&&n<cols){if(t[p+n]==' ')space=n;n++}"
    "var take=n;if(t[p+n]&&t[p+n]!='\\n'&&t[p+n]!=' '&&space>0)take=n=space;"
    "while(t[p+n]==' ')n++;if(t[p+n]=='\\n')n++;while(take&&t[p+take-1]==' ')take--;lines.push(t.slice(p,p+take));p+=n}while(p<t.length);return lines}"
    "function badgeError(){var s=$('badge_subject').value,b=$('badge_body').value;"
    "return s.length>256||b.length>1000?'Subject: up to 256 characters. Body: up to 1000.':"
    "/[^\\x20-\\x7e\\r\\n\\t]/.test(s+b)?'Use plain English letters, numbers, punctuation and line breaks.':''}"
    "function preview(){if(!font)return;var x=$('pv').getContext('2d'),o=x.createImageData(960,624),d=o.data;d.fill(255);"
    "function px(ch,r,c){return r>=0&&r<8&&c>=0&&c<8&&((font[ch*8+r]>>c)&1)}"
    "function big(y,s,t,ink){var X0=Math.floor((960-t.length*8*s)/2);for(var i=0;i<t.length;i++)for(var r=0;r<8;r++)for(var c=0;c<8;c++){"
    "var ch=t.charCodeAt(i),on=px(ch,r,c);for(var v=0;v<s;v++)for(var u=0;u<s;u++){"
    "var dy=v<Math.floor(s/2)?-1:1,dx=u<Math.floor(s/2)?-1:1,du=dx<0?u:s-1-u,dv=dy<0?v:s-1-v,"
    "a=px(ch,r,c+dx),b=px(ch,r+dy,c),corner=du+dv<Math.floor(s/2),set=on?!(corner&&!a&&!b&&!px(ch,r+dy,c+dx)):corner&&a&&b,"
    "X=X0+i*8*s+c*s+u,Y=y+r*s+v;if(set&&X>=0&&X<960&&Y>=0&&Y<624){var j=(Y*960+X)*4;d[j]=ink?140:255;d[j+1]=d[j+2]=ink?0:255}}}}"
    "function box(y,h){for(var Y=y;Y<y+h;Y++)for(var X=24;X<936;X++){var j=(Y*960+X)*4;d[j]=140;d[j+1]=d[j+2]=0}}"
    "var overflow=false;function section(t,y,h,preferred){var s=preferred,lines;while((lines=wrap(t,Math.floor(912/(8*s)))).length*10*s-2*s>h&&s>1)s--;"
    "var visible=Math.floor((h+2*s)/(10*s));if(lines.length>visible){overflow=true;lines=lines.slice(0,visible);lines[visible-1]='...'}"
    "y+=Math.floor((h-(lines.length*10*s-2*s))/2);lines.forEach(function(t){big(y,s,t,true);y+=10*s})}"
    "var s=normalise($('badge_subject').value),b=normalise($('badge_body').value);"
    "if(s&&b){section(s,24,184,10);section(b,232,368,6)}else if(s||b)section(s||b,24,576,12);"
    "else{box(16,228);big(40,13,'HELLO',false);big(160,5,'my name is',false);big(358,11,'Badge '+badgeId,true);box(560,48)}"
    "x.putImageData(o,0,0);$('pst').textContent=badgeError()||(overflow?'Too many line breaks to show everything; shorten the text or remove line breaks.':'Content preview; the badge adds its top bar.')}"
    "$('badge_subject').oninput=$('badge_body').oninput=function(){badgeEdited=true;preview()};"
    "$('link').oninput=function(){var s=decodeURIComponent(this.value),"
    "m=s.match(/!3d(-?[\\d.]+)!4d(-?[\\d.]+)/)||s.match(/@(-?[\\d.]+),\\s*(-?[\\d.]+)/)||s.match(/(-?\\d+\\.\\d+)\\s*,\\s*(-?\\d+\\.\\d+)/);"
    "if(m){$('wx_lat').value=m[1];$('wx_lon').value=m[2]}};"
    "$('file').onchange=function(){var f=this.files[0];if(!f)return;var im=new Image();im.onload=function(){"
    "var c=document.createElement('canvas');c.width=960;c.height=624;var x=c.getContext('2d');"
    "x.fillStyle='#fff';x.fillRect(0,0,960,624);var s=Math.min(960/im.width,624/im.height),w=im.width*s,h=im.height*s;"
    "x.drawImage(im,(960-w)/2,(624-h)/2,w,h);var d=x.getImageData(0,0,960,624).data;gray=new Float32Array(960*624);"
    "for(var i=0;i<gray.length;i++)gray[i]=.299*d[4*i]+.587*d[4*i+1]+.114*d[4*i+2];draw()};"
    "im.src=URL.createObjectURL(f)};"
    "$('th').oninput=$('dit').onchange=function(){if(gray)draw()};"
    "function draw(){var g=Float32Array.from(gray),t=+$('th').value,D=$('dit').checked;img=new Uint8Array(74880);"
    "var x=$('cv').getContext('2d'),o=x.createImageData(960,624);"
    "for(var y=0;y<624;y++)for(var X=0;X<960;X++){var i=y*960+X,v=g[i],k=v<t,e=v-(k?0:255);"
    "if(k)img[i>>3]|=128>>(i&7);o.data.set(k?[140,0,0,255]:[255,255,255,255],4*i);"
    "if(D){if(X<959)g[i+1]+=e*7/16;if(y<623){if(X)g[i+959]+=e*3/16;g[i+960]+=e*5/16;if(X<959)g[i+961]+=e/16}}}"
    "x.putImageData(o,0,0)}"
    "$('save').onclick=function(){if(!cfgReady){$('st').textContent='Settings are still loading. Try again shortly.';return}var b='',pic=$('mi').checked;"
    "if(new TextEncoder().encode($('ssid').value).length>32){$('st').textContent='Network name: up to 32 bytes.';return}"
    "if(!pic&&badgeEdited&&badgeError()){$('st').textContent=badgeError();return}"
    "var unchanged=pic||(!badgeEdited&&!hadImg),skip={badge_subject:unchanged,badge_body:unchanged,wx_city:$('wn').checked,wx_lat:$('wc').checked,wx_lon:$('wc').checked};"
    "K.forEach(function(k){if(!skip[k])b+=k+'\\0'+$(k).value+'\\0'});"
    "if(pic&&!img&&!hadImg){$('st').textContent='Choose a picture first.';return}"
    "$('st').textContent='Saving...';"
    "(pic&&img?fetch('/image',{method:'POST',body:img}):Promise.resolve({ok:1})).then(function(r){"
    "if(!r.ok)throw 'picture';return fetch('/save',{method:'POST',body:b})}).then(function(r){return r.text()})"
    ".then(function(t){$('st').textContent=t}).catch(function(e){$('st').textContent='Failed: '+e})}"
    "</script>";

